    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    sort(v.begin(), v.end());

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}

